package main

const dashboardHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Corex PC Companion</title><style>
:root{color-scheme:light;--bg:#f4f7f5;--surface:#fff;--surface2:#edf2ef;--text:#17211e;--muted:#65716c;--line:#d7dfda;--accent:#2f766d;--accent2:#1f6258;--soft:#e2f0ec;--danger:#b42318;--shadow:0 12px 34px rgba(20,42,34,.07)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea{font:inherit}.top{position:sticky;top:0;z-index:8;display:flex;align-items:center;justify-content:space-between;padding:13px 22px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.95);backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:12px}.mark{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:#174b82;color:#fff;font-weight:900;font-size:21px}.brand b{font-size:20px}.brand small{display:block;color:var(--muted)}.shell{display:grid;grid-template-columns:230px minmax(0,1fr);max-width:1440px;min-height:calc(100vh - 71px);margin:auto}.sidebar{padding:20px 14px;border-right:1px solid var(--line);background:var(--surface)}.nav{display:grid;gap:7px}.nav button,.nav a{display:flex;align-items:center;gap:11px;min-height:48px;padding:9px 12px;border:0;border-radius:13px;background:transparent;color:var(--text);text-align:left;text-decoration:none;font-weight:800;cursor:pointer}.nav button.on,.nav a.primary{background:var(--soft);color:var(--accent2)}.nav .icon{width:24px;text-align:center;font-size:19px}.sidebar .fine{margin:22px 8px 0}.content{min-width:0;padding:22px}.page{display:none}.page.on{display:block}.pagehead{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-bottom:16px}.pagehead h1{margin:0;font-size:28px}.pagehead p{margin:4px 0 0}.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px}.card{grid-column:span 12;border:1px solid var(--line);border-radius:20px;background:var(--surface);padding:18px;box-shadow:var(--shadow)}.card h2{margin:0 0 5px;font-size:19px}.card p{margin:4px 0 14px;color:var(--muted)}.hero{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.7fr);gap:18px;align-items:center;background:linear-gradient(135deg,var(--surface),var(--soft))}.hero h2{font-size:27px}.hero .btn{min-height:54px;font-size:16px}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.stat{padding:14px;border:1px solid var(--line);border-radius:15px;background:var(--surface2)}.stat b{display:block;font-size:24px;color:var(--accent)}.stat small{color:var(--muted);font-weight:750}.span7{grid-column:span 7}.span5{grid-column:span 5}.span6{grid-column:span 6}.btn,.address button{min-height:44px;padding:8px 13px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--text);font-weight:800;cursor:pointer}.btn.primary,.address button.on{border-color:var(--accent);background:var(--accent);color:#fff}.btn.danger{color:var(--danger)}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.status{margin-top:12px;padding:11px 13px;border-radius:12px;background:var(--soft);color:var(--accent2);font-weight:750}.pin{font-size:37px;font-weight:900;letter-spacing:.16em;color:var(--accent);text-align:center}.qr{display:block;width:min(230px,100%);aspect-ratio:1;margin:10px auto;border:1px solid var(--line);border-radius:16px;background:#fff}.method{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.method div{padding:10px;border:1px solid var(--line);border-radius:13px;background:var(--surface2)}.method b{display:block}.method small{color:var(--muted)}.address{display:grid;gap:7px}.device,.backup{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.device:last-child,.backup:last-child{border-bottom:0}.switch{display:flex;align-items:center;gap:9px;margin-top:14px}.switch input{width:18px;height:18px}.fine{font-size:12px;color:var(--muted)}.advanced{border:1px solid var(--line);border-radius:16px;overflow:hidden}.advanced summary{padding:14px;cursor:pointer;font-weight:850;background:var(--surface2)}.toolbar{display:grid;grid-template-columns:minmax(160px,1fr) auto auto;gap:8px;margin:12px 0}input,textarea{width:100%;border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:var(--surface);color:var(--text)}.records{display:grid;grid-template-columns:280px minmax(0,1fr);gap:14px}.keys{border:1px solid var(--line);border-radius:14px;overflow:auto;max-height:480px}.key{display:block;width:100%;padding:10px 12px;border:0;border-bottom:1px solid var(--line);background:var(--surface);color:var(--text);text-align:left;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.key.on{background:var(--soft);color:var(--accent2);font-weight:800}.editor{display:flex;flex-direction:column;gap:8px}.editor textarea{min-height:360px;resize:vertical;font:13px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace}.empty{padding:30px;text-align:center;color:var(--muted)}
@media(max-width:1000px){.shell{grid-template-columns:1fr}.sidebar{position:sticky;top:71px;z-index:6;border-right:0;border-bottom:1px solid var(--line);padding:8px}.nav{grid-template-columns:repeat(4,minmax(0,1fr))}.nav button,.nav a{justify-content:center;padding:7px;font-size:12px}.sidebar .fine{display:none}.hero{grid-template-columns:1fr}.span7,.span5,.span6{grid-column:span 12}.stats{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:700px){.top{padding:10px 12px}.brand b{font-size:16px}.content{padding:12px}.nav .icon{display:none}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.records{grid-template-columns:1fr}.keys{max-height:220px}.toolbar{grid-template-columns:1fr 1fr}.toolbar input{grid-column:1/-1}.method{grid-template-columns:1fr}.pagehead h1{font-size:23px}}
@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#151b19;--surface:#202724;--surface2:#28302d;--text:#eef4f1;--muted:#aeb9b4;--line:#3b4641;--soft:#263d38}.top{background:rgba(28,35,32,.95)}.hero{background:linear-gradient(135deg,var(--surface),var(--soft))}}
</style></head><body>
<header class="top"><div class="brand"><div class="mark">C</div><div><b>Corex PC Companion</b><small id="version">Secure local connection</small></div></div><button class="btn danger" id="stop">Stop Companion</button></header>
<div class="shell"><aside class="sidebar"><nav class="nav"><button class="on" data-page="home"><span class="icon">⌂</span>Overview</button><a class="primary" href="/app"><span class="icon">▣</span>Open Corex</a><button data-page="connection"><span class="icon">⌁</span>Connection</button><button data-page="safety"><span class="icon">↶</span>Backups</button></nav><p class="fine">One private desktop companion for the complete Corex workspace. No cloud account is required.</p></aside>
<main class="content">
<section class="page on" id="page-home"><div class="pagehead"><div><h1>Corex on your PC</h1><p>Use the complete Corex workspace with a large keyboard and screen.</p></div></div><div class="grid">
<article class="card hero"><div><h2>The full Corex interface is ready</h2><p>Open Focus, Priorities, Notes, To‑Do, Expense Manager, Trading Journal and Mileage with the same synchronized records as your phone.</p></div><a class="btn primary" href="/app" style="display:grid;place-items:center;text-decoration:none">Open full Corex</a></article>
<article class="card"><h2>Workspace summary</h2><p>Readable record totals from the latest protected phone synchronization.</p><div class="stats"><div class="stat"><b id="sumNotes">0</b><small>Notes</small></div><div class="stat"><b id="sumTodos">0</b><small>To‑Do</small></div><div class="stat"><b id="sumExpense">0</b><small>Expense data</small></div><div class="stat"><b id="sumTrading">0</b><small>Trading data</small></div><div class="stat"><b id="sumMileage">0</b><small>Mileage data</small></div></div></article>
<article class="card span7"><h2>Companion controls</h2><p id="homeSyncText">Waiting for the first phone synchronization.</p><div class="status" id="homeStatus">Revision 0</div><div class="actions"><button class="btn" id="homeRefresh">Refresh sync status</button><button class="btn" id="homeWindowsAlerts">Enable Windows reminders</button><button class="btn" data-open-page="connection">Connection</button><button class="btn" data-open-page="safety">Backups</button></div></article>
<article class="card span5"><h2>Connected phone</h2><div id="homeDevices" class="fine">No phone paired yet.</div><button class="btn" data-open-page="connection" style="margin-top:12px">Manage connection</button></article>
</div></section>
<section class="page" id="page-connection"><div class="pagehead"><div><h1>Connect your phone</h1><p>Choose Wi‑Fi, phone hotspot or USB tethering. The encrypted protocol is identical.</p></div></div><div class="grid">
<article class="card span5"><h2>Pair using QR or PIN</h2><div class="pin" id="pin">••••••</div><img class="qr" id="qr" alt="Corex pairing QR code"><div class="address" id="addresses"></div><div class="actions"><button class="btn" id="rotate">New PIN</button><button class="btn" id="refresh">Refresh networks</button></div><div class="status" id="pairStatus">Open Corex Settings → Connect PC and tap Scan PC QR code.</div></article>
<article class="card span7"><h2>Connection methods</h2><div class="method"><div><b>Wi‑Fi / Hotspot</b><small>Connect both devices to the same wireless network.</small></div><div><b>USB tethering</b><small>Connect the cable and enable USB tethering on the phone. Then refresh networks.</small></div></div><h2 style="margin-top:20px">Connected phones</h2><div id="devices" class="fine">No phone paired yet.</div><label class="switch"><input type="checkbox" id="autostart"> Start Corex Companion with Windows</label><p class="fine">Windows protected storage encrypts the saved connection and synchronized Corex snapshot.</p></article>
</div></section>
<section class="page" id="page-safety"><div class="pagehead"><div><h1>Backups and recovery</h1><p>Every PC edit creates a recoverable version before it synchronizes.</p></div></div><div class="grid"><article class="card span6"><h2>Safety versions</h2><div id="backups" class="empty">No safety versions yet.</div></article><article class="card span6"><h2>Export</h2><p>Download the current whole-workspace snapshot for offline storage.</p><a class="btn primary" href="/dashboard/export" style="display:inline-grid;place-items:center;text-decoration:none">Export Corex snapshot</a><div class="status" id="backupStatus">Current revision 0</div></article><article class="card"><details class="advanced"><summary>Advanced data — technical use only</summary><div style="padding:14px"><p>Internal storage values are hidden here so they do not replace the normal Corex interface.</p><div class="toolbar"><input id="search" placeholder="Search technical storage"><button class="btn" id="advancedRefresh">Refresh</button><button class="btn danger" id="advancedDelete">Delete selected</button></div><div class="records"><div class="keys" id="keys"><div class="empty">Waiting for synchronized data.</div></div><div class="editor"><input id="selected" readonly placeholder="Select an internal value"><textarea id="value" spellcheck="false" placeholder="Technical value"></textarea><button class="btn primary" id="advancedSave">Save technical change</button><div class="status" id="dataStatus">No technical value selected.</div></div></div></div></details></article></div></section>
</main></div>
<script>
const $=id=>document.getElementById(id);let state=null,data={},selected='',selectedHost='';const fmt=t=>t?new Date(t).toLocaleString():'Never';
async function api(path,options){const response=await fetch(path,options);const value=await response.json().catch(()=>({}));if(!response.ok)throw new Error(value.error||'Corex Companion request failed.');return value}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openPage(name){document.querySelectorAll('.page').forEach(page=>page.classList.toggle('on',page.id==='page-'+name));document.querySelectorAll('[data-page]').forEach(button=>button.classList.toggle('on',button.dataset.page===name))}
document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>openPage(button.dataset.page));document.querySelectorAll('[data-open-page]').forEach(button=>button.onclick=()=>openPage(button.dataset.openPage));
function renderAddresses(){const root=$('addresses');root.innerHTML='';const addresses=state.addresses||[];if(!selectedHost||!addresses.includes(selectedHost))selectedHost=addresses[0]||'';for(const address of addresses){const button=document.createElement('button');button.textContent=address+':'+state.port;button.classList.toggle('on',address===selectedHost);button.onclick=()=>{selectedHost=address;renderAddresses();renderQR()};root.appendChild(button)}if(!addresses.length)root.innerHTML='<div class="status">No local network detected. Enable Wi‑Fi, hotspot or USB tethering, then press Refresh networks.</div>'}
function renderQR(){if(selectedHost)$('qr').src='/dashboard/qr.svg?host='+encodeURIComponent(selectedHost)+'&t='+Date.now();else $('qr').removeAttribute('src')}
function deviceHtml(peers){if(!peers.length)return 'No phone paired yet.';return peers.map(p=>'<div class="device"><b>'+escapeHtml(p.name||'Corex phone')+'</b><small>'+escapeHtml(fmt(p.lastSeen))+'</small></div>').join('')}
function estimate(words){let total=0;for(const [key,raw]of Object.entries(data)){const lower=key.toLowerCase();if(!words.some(word=>lower.includes(word)))continue;try{const value=JSON.parse(raw);if(Array.isArray(value))total+=value.length;else if(value&&typeof value==='object')total+=Object.keys(value).length;else if(raw)total++}catch{if(raw)total++}}return total}
function summary(){$('sumNotes').textContent=estimate(['note']);$('sumTodos').textContent=estimate(['todo','to-do']);$('sumExpense').textContent=estimate(['expense']);$('sumTrading').textContent=estimate(['trad']);$('sumMileage').textContent=estimate(['mileage','fuel'])}
function renderBackups(){const root=$('backups'),versions=state.backups||[];if(!versions.length){root.className='empty';root.textContent='No safety versions yet.';return}root.className='';root.innerHTML=versions.map(item=>'<div class="backup"><div><b>Revision '+item.revision+'</b><small style="display:block;color:var(--muted)">'+escapeHtml(fmt(item.savedAt))+'</small></div><button class="btn" data-restore="'+item.revision+'">Restore</button></div>').join('');root.querySelectorAll('[data-restore]').forEach(button=>button.onclick=()=>restore(Number(button.dataset.restore)))}
async function restore(revision){if(!confirm('Restore revision '+revision+'? The current workspace will first be kept as another safety version.'))return;const result=await api('/dashboard/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision})});$('backupStatus').textContent='Restored safely as revision '+result.revision+' · synchronize the phone to receive it';await load()}
function filteredKeys(){const q=$('search').value.trim().toLowerCase();return Object.keys(data).sort().filter(key=>!q||key.toLowerCase().includes(q)||String(data[key]).toLowerCase().includes(q))}
function renderKeys(){const root=$('keys'),keys=filteredKeys();if(!keys.length){root.innerHTML='<div class="empty">No matching internal values.</div>';return}root.innerHTML='';for(const key of keys){const button=document.createElement('button');button.className='key'+(key===selected?' on':'');button.textContent=key;button.title=key;button.onclick=()=>selectKey(key);root.appendChild(button)}}
function selectKey(key){selected=key;$('selected').value=key;$('value').value=String(data[key]??'');renderKeys()}
async function saveSnapshot(message){const result=await api('/dashboard/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:JSON.stringify(data)})});state.revision=result.revision;$('dataStatus').textContent=message+' · Revision '+result.revision+' · ready for phone sync';renderKeys();return result}
async function load(){state=await api('/dashboard/state');$('version').textContent='Version '+state.version+' · Secure local connection';$('pin').textContent=state.pin;$('autostart').checked=!!state.autostart;try{data=JSON.parse(state.snapshot||'{}')}catch{data={}};const peers=state.peers||[];$('devices').innerHTML=deviceHtml(peers);$('homeDevices').innerHTML=deviceHtml(peers);$('homeSyncText').textContent=peers.length?'Phone connected. Open Corex to view and edit synchronized records.':'Pair your phone to begin encrypted synchronization.';$('homeStatus').textContent='Revision '+state.revision+' · Last refreshed '+new Date().toLocaleTimeString();$('backupStatus').textContent='Current revision '+state.revision;renderAddresses();renderQR();renderBackups();renderKeys();summary();if(selected&&Object.hasOwn(data,selected))selectKey(selected)}
$('rotate').onclick=async()=>{await api('/dashboard/rotate-pin',{method:'POST'});await load()};$('refresh').onclick=load;$('homeRefresh').onclick=load;$('advancedRefresh').onclick=load;$('search').oninput=renderKeys;
$('homeWindowsAlerts').onclick=async()=>{if(!('Notification'in window)){$('homeStatus').textContent='Windows reminders are unavailable in this browser.';return}const permission=await Notification.requestPermission();$('homeWindowsAlerts').textContent=permission==='granted'?'Windows reminders enabled':'Enable Windows reminders';$('homeStatus').textContent=permission==='granted'?'Windows reminders are enabled for Corex.':'Allow notifications for Corex PC Companion in Windows.'};
$('advancedSave').onclick=async()=>{if(!selected)return;data[selected]=$('value').value;try{await saveSnapshot('Saved '+selected)}catch(e){alert(e.message)}};$('advancedDelete').onclick=async()=>{if(!selected||!confirm('Delete this technical value? A safety version will remain on this PC.'))return;const old=selected;delete data[selected];selected='';$('selected').value='';$('value').value='';try{await saveSnapshot('Deleted '+old)}catch(e){alert(e.message)}};
$('autostart').onchange=async e=>{try{await api('/dashboard/autostart',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:e.target.checked})})}catch(error){e.target.checked=!e.target.checked;alert(error.message)}};
$('stop').onclick=async()=>{if(!confirm('Stop Corex PC Companion? Phone synchronization and desktop reminders will pause.'))return;await api('/dashboard/exit',{method:'POST'});document.body.innerHTML='<div class="empty"><h2>Corex PC Companion stopped</h2><p>You can close this browser tab.</p></div>'};
load().catch(e=>$('pairStatus').textContent=e.message);setInterval(()=>load().catch(()=>{}),15000);
</script></body></html>`
